<?php

declare(strict_types=1);

namespace App\Services\Llm;

use App\Models\ScenarioRequest;

/** Validated input facts, not a prewritten scenario or fallback completion. */
class PedagogicalTaskBrief
{
    public function forRequest(ScenarioRequest $request): array
    {
        $core = ['setting' => 'Все участники и получатели помощи вымышлены. Только бумага, карандаши и доска; никакой покупки техники, персональных историй или интернета.',
            'challenge' => 'Спроектируйте справедливую подготовку трёх одинаковых комплектов для трёх школьных рабочих зон. Нужно учитывать одновременно потребности каждой зоны, общий запас и резерв; решение должно быть понятно другой команде.',
            'facts' => ['zones' => 3, 'paper_available' => 18, 'pencils_available' => 12, 'paper_per_kit' => 5, 'pencils_per_kit' => 3, 'minimum_paper_reserve' => 3, 'minimum_pencil_reserve' => 2],
            'verified_solution' => ['kits' => 3, 'paper_used' => 15, 'pencils_used' => 9, 'paper_remaining' => 3, 'pencils_remaining' => 3, 'reserve_constraints_met' => true],
            'distributed_information' => ['Хранитель запасов знает только общий запас; не выдавайте ему все условия сразу.', 'Представитель получателя знает потребность одного комплекта.', 'Хранитель резерва знает ограничение на резерв.', 'Проверяющий собирает аргументы и проверяет обе величины; докладчик объясняет, почему ни одна группа не осталась без помощи.'],
            'second_challenge' => 'Сравните два плана: всем зонам одинаковый комплект (проверенное решение) или одной зоне дополнительный лист. Второй план оставляет только2 листа в резерве и нарушает ограничение3. Команда должна предложить справедливый план без нарушения резерва и объяснить отказ без обвинений.',
            'answer_check' => '18-15=3; 12-9=3. Дополнительный лист уменьшает бумажный резерв до2, поэтому сначала согласовать изменение потребностей или отказаться от перераспределения. Важно не считать скорость победой: решение принимается только после высказывания каждого носителя данных.'];
        if ($request->scale === 'all_school') {
            $count = (int) $request->participants_count;
            $groups = (int) ceil($count / 15);
            $schedule = [];
            for ($round = 0; $round < 5; $round++) {
                $assign = [];
                for ($g = 1; $g <= $groups; $g++) {
                    $assign['Группа '.$g] = 'Зона '.((intdiv($g - 1, 2) + $round) % 5 + 1);
                }$schedule[] = ['round' => $round + 1, 'minutes' => [18 + $round * 6, 24 + $round * 6], 'work_minutes' => 4, 'move_minutes' => 2, 'assignments' => $assign];
            }
            $core['logistics'] = ['schedule_for_60_minutes' => $request->duration_minutes === 60 ? $schedule : [], 'participants' => $count, 'groups' => $groups, 'maximum_group_size' => 15, 'zones' => 5, 'groups_per_zone' => (int) ceil($groups / 5),
                'main_stage_minutes' => (int) $request->duration_minutes - (int) floor($request->duration_minutes * .1) - (int) floor($request->duration_minutes * .2) - (int) floor($request->duration_minutes * .2),
                'for_150' => '10 групп по15; пять зон с двумя группами в каждой. Основной этап30 минут: пять раундов по4 минуты работы +2 минуты перехода, включая последний возврат. Всего20 минут работы и10 минут переходов. В зале зоны размечены бумажными номерами; запустить маршрут только после проверки вместимости педагогом. В каждой зоне взрослый координатор; если пяти взрослых нет, синхронные задания за столами без переходов, с теми же временными раундами.',
                'zone_tasks' => ['Обмен сведениями о запасах', 'Проверка потребностей трёх получателей', 'Проверка резервов и двух альтернатив', 'Распределение действий без исключённых участников', 'Взаимная проверка и корректная обратная связь'],
                'roles' => 'Внутри группы15 пять ролевых подгрупп по3, распределите носителей данных, проверяющих, координатора и докладчиков. Печатные материалы для всех пяти раундов, не оставляйте две карточки на весь маршрут без объяснения повторного использования.'];
        }
        if ($request->scale === 'family_community') {
            $core['family_workshop'] = ['product' => 'Общий бумажный план школьной взаимопомощи с проверкой ресурсов и доступностью каждой роли.',
                'main_45_minutes' => ['15 минут: ребёнок и добровольный взрослый/наставник предлагают свои планы, обмениваются раздельными данными, согласуют решение.', '15 минут: создают бумажный план, меняются ролями проверяющего и исполнителя.', '15 минут: другая смешанная группа проверяет план и ограничения; авторы исправляют его и объясняют изменения.'],
                'inclusion' => 'Ребёнок без родственника выбирает школьного наставника или равноправную смешанную группу без объяснения причин. Все роли доступны независимо от наличия взрослого, никаких семейных фото, историй и сведений о семье.',
                'adult_role' => 'Взрослый или добровольный наставник задаёт уточняющие вопросы, помогает зафиксировать доводы ребёнка и затем меняется с ним ролью проверяющего. Он не решает за ребёнка. Если взрослого нет, те же действия доступны ребёнку-партнёру или школьному наставнику без объяснения причин.',
                'full_duration' => '90 минут, не45: отдельные9 минут знакомства/распределения ролей,18 минут репетиции процедуры обмена на нейтральном примере без чисел и решения основной задачи,45 минут мастерской,18 минут демонстрации/рефлексии. В каждом блоке есть реальные действия, обмен ролями и готовые материалы.'];
        }

        return $core;
    }
}
